"""Chapter generation: configuration and pure, deterministic planning.

Nothing here touches files, the database, or the network. Media inspection
lives in mediafile.py, transcription in transcribe.py, the Ollama step in
semantic.py, and job orchestration in enrichment.py.

Times are seconds from the start of the media.
"""

import copy
import hashlib
import json
from dataclasses import dataclass, field
from itertools import pairwise
from typing import Any

# Raise when planning output for the same inputs changes, so items generated by
# an older version can be found and regenerated on request.
GENERATION_VERSION = 1

# Do not place a chapter this close to the end (credits, "previously on").
END_MARGIN_SECONDS = 120

DEFAULTS: dict[str, Any] = {
    "enabled": False,
    "mode": "smart",
    "minimum_duration_minutes": 20,
    "preserve_existing": True,
    "target_spacing_minutes": 7,
    "minimum_spacing_minutes": 4,
    "maximum_spacing_minutes": 10,
    "semantic": {
        "enabled": True,
        "transcription": "faster-whisper",
        "model": "medium",
        "llm": "ollama",
        "llm_model": "",
    },
    "fallback": {
        "scene_detection": True,
        "fixed_intervals": True,
    },
    "naming": {
        "semantic_names": True,
        "fallback_format": "Chapter {number}",
    },
    "processing": {
        "new_media": True,
        "existing_library": False,
        "dry_run": False,
    },
    "subtitles": {
        "enabled": False,
        # Picture subtitles (Blu-ray PGS, DVD VobSub) can't be shown by most
        # TV apps, so Jellyfin burns them into the video: a restart, a
        # transcode, slow seeking. A text track beside them avoids that.
        "replace_pictures": True,
    },
}

# Values that only make sense once per installation, not per library.
# A ceiling only: the adaptive limit (adaptive.py) decides how many actually run.
# Transcription takes the GPU one at a time, but scene detection (~1.5 cores
# each), reading files and waiting on the language model overlap.
MAX_CONCURRENCY = 8

GLOBAL_DEFAULTS: dict[str, Any] = {
    "concurrency": 1,
    "pause_during_playback": True,
    "movie_credits_only": True,
    "episode_identity_check": False,
    "dub_check": True,
    "dub_replace_automatically": True,
    "dub_remove_other_languages": False,
    "file_check": True,
    "file_replace_automatically": True,
    "compat_audio": False,
    # A stereo AAC track for browsers (with the Curatarr plugin for Jellyfin,
    # which points them at it; without it the track would go unused).
    "browser_audio": True,
    "fix_default_audio": True,
    "finish_at_credits": True,
    "seek_repair": True,
    "pace_rebuilds": True,
    "settle_minutes": 10,
    "scene_threshold": 0.3,
    "ollama_url": "http://127.0.0.1:11434",
    "whisper_device": "auto",
    "path_mappings": [],
}

MODES = {"navigation", "smart"}
WHISPER_MODELS = {
    "tiny",
    "base",
    "small",
    "medium",
    "large-v2",
    "large-v3",
    "turbo",
    "distil-large-v3",
}
WHISPER_DEVICES = {"auto", "cuda", "cpu"}

STATUSES = (
    "not_processed",
    "existing",
    "generated_semantic",
    "generated_scene_aligned",
    "generated_fixed",
    "skipped_short",
    "unsupported_container",
    "failed",
    "dry_run",
    "removed",
)
GENERATED_STATUSES = {
    "semantic": "generated_semantic",
    "scene_aligned": "generated_scene_aligned",
    "fixed": "generated_fixed",
}
SOURCE_LABELS = {
    "embedded": "Embedded",
    "semantic": "Semantic",
    "scene_aligned": "Scene-aligned",
    "fixed": "Fixed interval",
}


class ChapterConfigError(ValueError):
    pass


def _merge(base: dict, layer: dict) -> dict:
    merged = copy.deepcopy(base)
    for key, value in (layer or {}).items():
        if isinstance(value, dict) and isinstance(merged.get(key), dict):
            merged[key] = _merge(merged[key], value)
        else:
            merged[key] = copy.deepcopy(value)
    return merged


def _check_shape(layer: dict, template: dict, prefix=""):
    for key, value in layer.items():
        name = f"{prefix}{key}"
        if key not in template:
            raise ChapterConfigError(f"Unknown chapter setting: {name}")
        expected = template[key]
        if isinstance(expected, dict):
            if not isinstance(value, dict):
                raise ChapterConfigError(f"Invalid {name}")
            _check_shape(value, expected, f"{name}.")
        elif isinstance(expected, bool):
            if type(value) is not bool:
                raise ChapterConfigError(f"Invalid {name}")
        elif isinstance(expected, int):
            if type(value) is not int:
                raise ChapterConfigError(f"Invalid {name}")
        elif isinstance(expected, str) and not isinstance(value, str):
            raise ChapterConfigError(f"Invalid {name}")


def validate_layer(layer: dict) -> dict:
    """Check one stored layer (global or library); partial layers are allowed."""
    if not isinstance(layer, dict):
        raise ChapterConfigError("Chapter settings must be an object")
    _check_shape(layer, DEFAULTS)
    validate_config(_merge(DEFAULTS, layer))
    return layer


def validate_config(config: dict) -> dict:
    if config["mode"] not in MODES:
        raise ChapterConfigError("Mode must be navigation or smart")
    for key, low, high in (
        ("minimum_duration_minutes", 1, 600),
        ("target_spacing_minutes", 1, 120),
        ("minimum_spacing_minutes", 1, 120),
        ("maximum_spacing_minutes", 1, 240),
    ):
        if not low <= config[key] <= high:
            raise ChapterConfigError(f"{key.replace('_', ' ')} must be {low}-{high}")
    if not (
        config["minimum_spacing_minutes"]
        <= config["target_spacing_minutes"]
        <= config["maximum_spacing_minutes"]
    ):
        raise ChapterConfigError("Spacing must satisfy minimum ≤ target ≤ maximum")
    if config["mode"] == "navigation" and not (
        config["fallback"]["scene_detection"] or config["fallback"]["fixed_intervals"]
    ):
        raise ChapterConfigError(
            "Navigation Chapters needs scene alignment or fixed intervals"
        )
    if config["mode"] == "smart" and not (
        config["semantic"]["enabled"]
        or config["fallback"]["scene_detection"]
        or config["fallback"]["fixed_intervals"]
    ):
        raise ChapterConfigError("Smart Chapters needs at least one method enabled")
    if config["semantic"]["model"] not in WHISPER_MODELS:
        raise ChapterConfigError("Unknown transcription model")
    if config["semantic"]["transcription"] != "faster-whisper":
        raise ChapterConfigError("faster-whisper is the only transcription engine")
    if config["semantic"]["llm"] != "ollama":
        raise ChapterConfigError("Ollama is the only local AI provider")
    fallback_format = config["naming"]["fallback_format"]
    if "{number}" not in fallback_format or len(fallback_format) > 60:
        raise ChapterConfigError("Fallback names must contain {number}")
    try:
        fallback_format.format(number=1)
    except (IndexError, KeyError, ValueError) as exc:
        raise ChapterConfigError("Fallback names may only use {number}") from exc
    return config


def effective_config(global_layer=None, library_layer=None) -> dict:
    """Built-in defaults, then the global layer, then one library's layer."""
    config = _merge(_merge(DEFAULTS, global_layer or {}), library_layer or {})
    return validate_config(config)


def validate_global_options(values: dict) -> dict:
    merged = GLOBAL_DEFAULTS | (values or {})
    unknown = set(values or {}) - set(GLOBAL_DEFAULTS)
    if unknown:
        raise ChapterConfigError(f"Unknown setting: {min(unknown)}")
    if (
        type(merged["concurrency"]) is not int
        or not 1 <= merged["concurrency"] <= MAX_CONCURRENCY
    ):
        raise ChapterConfigError(f"Chapter jobs at once must be 1-{MAX_CONCURRENCY}")
    if (
        type(merged["settle_minutes"]) is not int
        or not 1 <= merged["settle_minutes"] <= 1440
    ):
        raise ChapterConfigError("Settle time must be 1-1440 minutes")
    threshold = merged["scene_threshold"]
    if not isinstance(threshold, int | float) or not 0.05 <= threshold <= 0.95:
        raise ChapterConfigError("Scene threshold must be between 0.05 and 0.95")
    if type(merged["pause_during_playback"]) is not bool:
        raise ChapterConfigError("Invalid pause during playback")
    if type(merged["movie_credits_only"]) is not bool:
        raise ChapterConfigError("Invalid movie skip-marker setting")
    if type(merged["episode_identity_check"]) is not bool:
        raise ChapterConfigError("Invalid episode check setting")
    if type(merged["dub_check"]) is not bool:
        raise ChapterConfigError("Invalid dub check setting")
    if type(merged["dub_replace_automatically"]) is not bool:
        raise ChapterConfigError("Invalid dub replacement setting")
    if type(merged["dub_remove_other_languages"]) is not bool:
        raise ChapterConfigError("Invalid setting for removing other languages")
    if type(merged["file_check"]) is not bool:
        raise ChapterConfigError("Invalid file check setting")
    if type(merged["file_replace_automatically"]) is not bool:
        raise ChapterConfigError("Invalid file replacement setting")
    if type(merged["compat_audio"]) is not bool:
        raise ChapterConfigError("Invalid TV-friendly audio setting")
    if type(merged["browser_audio"]) is not bool:
        raise ChapterConfigError("Invalid browser audio setting")
    if type(merged["fix_default_audio"]) is not bool:
        raise ChapterConfigError("Invalid default audio setting")
    if type(merged["finish_at_credits"]) is not bool:
        raise ChapterConfigError("Invalid finished-at-credits setting")
    if type(merged["seek_repair"]) is not bool:
        raise ChapterConfigError("Invalid seek repair setting")
    if type(merged["pace_rebuilds"]) is not bool:
        raise ChapterConfigError("Invalid rebuild pacing setting")
    if merged["whisper_device"] not in WHISPER_DEVICES:
        raise ChapterConfigError("Transcription device must be auto, cuda, or cpu")
    if not str(merged["ollama_url"]).startswith(("http://", "https://")):
        raise ChapterConfigError("Ollama URL must start with http:// or https://")
    for mapping in merged["path_mappings"]:
        if (
            not isinstance(mapping, dict)
            or set(mapping) != {"arr", "local"}
            or not all(isinstance(v, str) and v for v in mapping.values())
        ):
            raise ChapterConfigError("Path mappings need an arr path and a local path")
    return merged


def config_hash(config: dict) -> str:
    """Identifies the settings that shape generated chapters."""
    relevant = {
        key: config[key]
        for key in (
            "mode",
            "target_spacing_minutes",
            "minimum_spacing_minutes",
            "maximum_spacing_minutes",
            "semantic",
            "fallback",
            "naming",
        )
    }
    relevant["version"] = GENERATION_VERSION
    return hashlib.sha256(json.dumps(relevant, sort_keys=True).encode()).hexdigest()[
        :16
    ]


@dataclass(frozen=True)
class Spacing:
    target: float
    minimum: float
    maximum: float

    @classmethod
    def from_config(cls, config: dict) -> "Spacing":
        return cls(
            config["target_spacing_minutes"] * 60.0,
            config["minimum_spacing_minutes"] * 60.0,
            config["maximum_spacing_minutes"] * 60.0,
        )


@dataclass(frozen=True)
class Window:
    """Where the chapter after ``previous`` may start."""

    previous: float
    earliest: float
    target: float
    latest: float


def next_window(previous: float, duration: float, spacing: Spacing) -> Window | None:
    """The allowed range for the next boundary, or None when the media ends first."""
    last_allowed = duration - END_MARGIN_SECONDS
    earliest = previous + spacing.minimum
    latest = min(previous + spacing.maximum, last_allowed)
    if earliest > latest:
        return None
    target = min(max(previous + spacing.target, earliest), latest)
    return Window(previous, earliest, target, latest)


@dataclass
class Chapter:
    start: float
    name: str = ""

    def as_dict(self):
        return {"start": round(self.start, 3), "name": self.name}


@dataclass
class Plan:
    method: str  # semantic, scene_aligned, fixed
    chapters: list[Chapter]
    notes: list[str] = field(default_factory=list)

    def as_dict(self):
        return {
            "method": self.method,
            "chapters": [chapter.as_dict() for chapter in self.chapters],
            "notes": list(self.notes),
        }


def fallback_name(config: dict, number: int) -> str:
    return config["naming"]["fallback_format"].format(number=number)


def _named(starts: list[float], config: dict) -> list[Chapter]:
    return [
        Chapter(start, fallback_name(config, number))
        for number, start in enumerate(starts, start=1)
    ]


def fixed_interval_plan(duration: float, config: dict) -> Plan:
    spacing = Spacing.from_config(config)
    starts = [0.0]
    while window := next_window(starts[-1], duration, spacing):
        starts.append(window.target)
    return Plan("fixed", _named(starts, config))


def nearest(candidates, window: Window):
    """The candidate inside the window closest to its target (earlier on ties)."""
    inside = [t for t in candidates if window.earliest <= t <= window.latest]
    if not inside:
        return None
    return min(inside, key=lambda t: (abs(t - window.target), t))


def scene_aligned_plan(duration: float, scenes: list[float], config: dict) -> Plan:
    """Each boundary moves to the scene change nearest its target spacing.

    A window with no scene change keeps the target time, so one quiet stretch
    does not fail the whole plan.
    """
    spacing = Spacing.from_config(config)
    ordered = sorted(scenes)
    starts, unaligned = [0.0], 0
    while window := next_window(starts[-1], duration, spacing):
        choice = nearest(ordered, window)
        if choice is None:
            unaligned += 1
            choice = window.target
        starts.append(choice)
    notes = []
    if unaligned:
        notes.append(
            f"{unaligned} boundar{'y' if unaligned == 1 else 'ies'} had no scene "
            "change within the allowed spacing and use the target time."
        )
    return Plan("scene_aligned", _named(starts, config), notes)


class InvalidChapters(ValueError):
    pass


def validate_chapters(chapters: list[Chapter], duration: float) -> list[Chapter]:
    """Starts at zero, strictly increasing, inside the media, with sane names."""
    if not chapters:
        raise InvalidChapters("No chapters were produced")
    if duration <= 0:
        raise InvalidChapters("Media duration is unknown")
    if chapters[0].start != 0:
        raise InvalidChapters("The first chapter must start at 00:00:00")
    previous = -1.0
    for chapter in chapters:
        if not 0 <= chapter.start < duration:
            raise InvalidChapters(
                f"Chapter at {timestamp(chapter.start)} is outside the media"
            )
        if chapter.start <= previous:
            raise InvalidChapters("Chapter times must increase")
        if not chapter.name or len(chapter.name) > 80 or "\n" in chapter.name:
            raise InvalidChapters("Chapter names must be one short line")
        previous = chapter.start
    return chapters


def timestamp(seconds: float) -> str:
    millis = round(seconds * 1000)
    hours, millis = divmod(millis, 3_600_000)
    minutes, millis = divmod(millis, 60_000)
    secs, millis = divmod(millis, 1000)
    return f"{hours:02}:{minutes:02}:{secs:02}.{millis:03}"


def chapter_file_text(chapters: list[Chapter]) -> str:
    """The simple (OGM) chapter format that mkvpropedit --chapters reads."""
    lines = []
    for number, chapter in enumerate(chapters, start=1):
        lines.append(f"CHAPTER{number:02}={timestamp(chapter.start)}")
        lines.append(f"CHAPTER{number:02}NAME={chapter.name}")
    return "\n".join(lines) + "\n"


def fingerprint(chapters) -> str:
    """Identifies a chapter list as read back from the file (millisecond times)."""
    normalized = [
        [
            round(float(c["start"] if isinstance(c, dict) else c.start), 3),
            (c["name"] if isinstance(c, dict) else c.name).strip(),
        ]
        for c in chapters
    ]
    return hashlib.sha256(json.dumps(normalized).encode()).hexdigest()


# --- Semantic planning helpers (the Ollama call itself is injected) ---------


@dataclass(frozen=True)
class Segment:
    start: float
    end: float
    text: str


PAUSE_SECONDS = 2.0  # a gap in speech at least this long is a candidate boundary
CANDIDATE_MERGE_SECONDS = 4.0
MAX_CANDIDATES = 10


@dataclass(frozen=True)
class Candidate:
    time: float
    scene: bool
    pause: bool

    @property
    def label(self):
        kinds = [
            k for k, v in (("scene change", self.scene), ("pause", self.pause)) if v
        ]
        return " + ".join(kinds)


def candidates_in(window: Window, scenes: list[float], segments: list[Segment]):
    """Scene changes and speech pauses inside a window, nearest the target first.

    A scene change inside a pause is the strongest kind of candidate, so the two
    are merged when they fall within a few seconds of each other.
    """
    found: list[Candidate] = []
    for time in scenes:
        if window.earliest <= time <= window.latest:
            found.append(Candidate(time, True, False))
    for before, after in pairwise(segments):
        gap = after.start - before.end
        if gap >= PAUSE_SECONDS:
            middle = before.end + gap / 2
            if window.earliest <= middle <= window.latest:
                scene = next(
                    (
                        c
                        for c in found
                        if c.scene and before.end <= c.time <= after.start
                    ),
                    None,
                )
                if scene:
                    found.remove(scene)
                    found.append(Candidate(scene.time, True, True))
                else:
                    found.append(Candidate(middle, False, True))
    found.sort(key=lambda c: c.time)
    merged: list[Candidate] = []
    for candidate in found:
        if merged and candidate.time - merged[-1].time < CANDIDATE_MERGE_SECONDS:
            keep = max(
                merged[-1], candidate, key=lambda c: (c.scene and c.pause, c.scene)
            )
            merged[-1] = keep
        else:
            merged.append(candidate)
    merged.sort(key=lambda c: (abs(c.time - window.target), c.time))
    chosen = merged[:MAX_CANDIDATES]
    return sorted(chosen, key=lambda c: c.time)


def transcript_excerpt(segments: list[Segment], start: float, end: float, limit=3500):
    """Timestamped lines between two times, trimmed to a character budget."""
    lines = [
        f"[{timestamp(s.start)[:8]}] {s.text.strip()}"
        for s in segments
        if s.end >= start and s.start <= end and s.text.strip()
    ]
    text = "\n".join(lines)
    if len(text) <= limit:
        return text
    # Keep both ends: what leads into the window and what follows it.
    half = limit // 2
    return text[:half] + "\n[…]\n" + text[-half:]


def clean_name(value, fallback: str) -> str:
    if not isinstance(value, str):
        return fallback
    name = " ".join(value.replace("\n", " ").split()).strip(" \"'.:-")
    if not name or len(name) > 60:
        return fallback
    return name


RECAP_CHAPTER_NAME = "Previously On"


def semantic_plan(duration, scenes, segments, config, choose, name, recap=None) -> Plan:
    """Boundaries chosen by the language model from scene/pause candidates.

    ``choose(window, candidates, excerpt)`` returns an index into ``candidates``
    or None; ``name(chapters_with_excerpts)`` returns one name per chapter.
    Both are injected so the planning rules are testable without Ollama.
    A ``recap`` (see recaps.py) becomes a first chapter named "Previously On";
    the episode's own chapters are planned from where it ends.
    """
    if not segments:
        raise InvalidChapters("The transcript has no speech")
    spacing = Spacing.from_config(config)
    starts, notes, chosen_by_model, asked = [0.0], [], 0, 0
    if recap is not None:
        starts.append(recap.end)
        notes.append(
            f"Recap until {timestamp(recap.end)[:8]} (found from the {recap.source})."
        )
    while window := next_window(starts[-1], duration, spacing):
        candidates = candidates_in(window, scenes, segments)
        pick = None
        if candidates:
            excerpt = transcript_excerpt(
                segments, window.earliest - 60, window.latest + 60
            )
            asked += 1
            index = choose(window, candidates, excerpt)
            if index is not None and 0 <= index < len(candidates):
                pick = candidates[index].time
                chosen_by_model += 1
            else:
                pick = candidates[
                    min(
                        range(len(candidates)),
                        key=lambda i: abs(candidates[i].time - window.target),
                    )
                ].time
        else:
            pick = window.target
        starts.append(pick)
    # Refusing every choice it was offered suggests the model isn't working. Having
    # nothing to choose from (no scene changes or pauses, common in older shows
    # with continuous music) isn't a model failure: keep even spacing, still name.
    fixed = 1 if recap is not None else 0  # the recap boundary wasn't chosen
    boundaries = len(starts) - 1 - fixed
    if asked and not chosen_by_model:
        raise InvalidChapters("The language model did not choose any boundary")
    if not asked and boundaries > 0:
        notes.append(
            "No scene changes or pauses were found, so chapters are evenly spaced."
        )
    elif chosen_by_model < boundaries:
        notes.append(
            f"{boundaries - chosen_by_model} boundar"
            f"{'y' if boundaries - chosen_by_model == 1 else 'ies'} used the "
            "nearest candidate because the model gave no usable choice."
        )
    chapters = [Chapter(start) for start in starts]
    own = chapters[fixed:]
    if config["naming"]["semantic_names"]:
        excerpts = []
        for index, chapter in enumerate(own):
            end = own[index + 1].start if index + 1 < len(own) else duration
            excerpts.append(
                (chapter.start, transcript_excerpt(segments, chapter.start, end, 3000))
            )
        names = name(excerpts) or []
        for index, chapter in enumerate(own):
            fallback = fallback_name(config, index + 1)
            chapter.name = clean_name(
                names[index] if index < len(names) else None, fallback
            )
        if len({c.name for c in own}) < len(own):
            notes.append("Some generated names repeat.")
    else:
        for index, chapter in enumerate(own):
            chapter.name = fallback_name(config, index + 1)
    if fixed:
        chapters[0].name = RECAP_CHAPTER_NAME
    return Plan("semantic", chapters, notes)
